                    {tab.badge}
                  </span>
                ) : null}
              </div>
              <span className="font-mono text-[10px] tracking-wider uppercase mt-1">
                {tab.label}
              </span>
              {isActive && (
                <span className="w-1 h-1 rounded-full bg-[#835331] mt-0.5" />
              )}
