import React, { useState, useRef, useEffect } from 'react';
import {
  X,
  Send,
  Sparkles,
  Bot,
  User,
  ExternalLink,
  Loader2,
  FileCode,
  CornerDownLeft,
} from 'lucide-react';
import type { ChatMessage, Project } from '../types';
import { apiFetch } from '../services/api';

interface ChatDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  project: Project;
  onSelectFile?: (filePath: string, line?: number) => void;
}

export const ChatDrawer: React.FC<ChatDrawerProps> = ({
  isOpen,
  onClose,
  project,
  onSelectFile,
}) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: 'welcome',
      role: 'assistant',
      content: `I am **DevLens Intelligence**, initialized on repository \`${project.name}\`. Every answer is grounded directly in indexed AST chunks, declared manifests, and source files.\n\nAsk me about architecture, concurrency, security findings, or how specific modules operate.`,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    },
  ]);
  const [inputQuery, setInputQuery] = useState('');
  const [isQuerying, setIsQuerying] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen) {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isOpen]);

  if (!isOpen) return null;

  const handleSend = async (textToSend?: string) => {
    const q = (textToSend || inputQuery).trim();
    if (!q || isQuerying) return;

    const userMsg: ChatMessage = {
      id: `user-${Date.now()}`,
      role: 'user',
      content: q,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    };

    setMessages((prev) => [...prev, userMsg]);
    if (!textToSend) setInputQuery('');
    setIsQuerying(true);

    try {
      const res = await apiFetch(`/api/projects/${project.id}/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ question: q }),
      });
      const data = await res.json();

      const assistantMsg: ChatMessage = {
        id: `ai-${Date.now()}`,
        role: 'assistant',
        content: data.text || 'Unable to analyze codebase query.',
        citations: data.citations || [],
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      };

      setMessages((prev) => [...prev, assistantMsg]);
    } catch (err) {
      setMessages((prev) => [
        ...prev,
        {
          id: `err-${Date.now()}`,
          role: 'assistant',
          content: 'Error communicating with the repository intelligence server.',
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        },
      ]);
    } finally {
      setIsQuerying(false);
    }
  };

  const sampleQueries = [
    'How does authentication work in this project?',
    'Where is the API / ingress layer implemented?',
    'What causes the concurrency anomaly in runtime/scheduler.go?',
    'Which files define the gRPC contracts and schema?',
  ];

  return (
    <div className="fixed inset-0 z-50 flex justify-end bg-[#1c1c18]/40 backdrop-blur-xs animate-in fade-in duration-150">
      <div className="w-full sm:w-[540px] h-full bg-[#ffffff] border-l border-[#c8c5cb] shadow-2xl flex flex-col justify-between">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-[#c8c5cb]/50 bg-[#fdf9f2]">
          <div className="flex items-center space-x-2">
            <div className="p-1.5 rounded bg-[#1c1c18] text-[#febf94]">
              <Sparkles className="w-4 h-4" />
            </div>
            <div>
              <h3 className="font-serif text-lg font-bold text-[#1c1c18] leading-tight">
                Conversation With the Code
              </h3>
              <p className="font-mono text-[10px] text-[#78767b]">
                Grounded RAG on {project.name} ({project.totalFiles} files indexed)
              </p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="p-1 text-[#47464b] hover:text-[#1c1c18] hover:bg-[#ece8e1] rounded transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Message Thread */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-[#fdf9f2]/50">
          {messages.map((m) => {
            const isUser = m.role === 'user';
            return (
              <div
                key={m.id}
                className={`flex flex-col ${isUser ? 'items-end' : 'items-start'} space-y-1`}
              >
                <div className="flex items-center space-x-1.5 text-[10px] font-mono text-[#78767b]">
                  {isUser ? <span>Developer</span> : <span className="text-[#835331] font-semibold">DevLens AI</span>}
                  <span>&bull;</span>
                  <span>{m.timestamp}</span>
                </div>

                <div
                  className={`p-3.5 rounded-lg max-w-[92%] font-sans text-xs sm:text-sm leading-relaxed whitespace-pre-wrap ${
                    isUser
                      ? 'bg-[#1c1c18] text-[#ffffff] font-medium'
                      : 'bg-[#ffffff] text-[#1c1c18] border border-[#c8c5cb]/60 bevel-hairline-subtle'
                  }`}
                >
                  {m.content}

                  {/* Grounded Source Citations */}
                  {m.citations && m.citations.length > 0 && (
                    <div className="mt-3 pt-2.5 border-t border-[#c8c5cb]/40 space-y-1">
                      <div className="font-mono text-[10px] uppercase text-[#835331] font-semibold">
                        Referenced Repository Sources:
                      </div>
                      <div className="flex flex-wrap gap-1.5">
                        {m.citations.map((c, i) => (
                          <button
                            key={i}
                            onClick={() => {
                              if (onSelectFile) onSelectFile(c.file, c.startLine);
                              onClose();
                            }}
                            className="font-mono text-[10.5px] bg-[#f7f3ec] hover:bg-[#ece8e1] border border-[#c8c5cb] px-2 py-1 rounded text-[#1c1c18] flex items-center space-x-1 transition-all"
                            title={c.snippet}
                          >
                            <FileCode className="w-3 h-3 text-[#835331]" />
                            <span>
                              {c.file}:{c.startLine}-{c.endLine}
                            </span>
                            <ExternalLink className="w-2.5 h-2.5 ml-0.5 text-[#78767b]" />
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            );
          })}

          {isQuerying && (
            <div className="flex items-center space-x-2 text-xs font-mono text-[#835331] bg-[#ffffff] p-3 rounded border border-[#c8c5cb]/40 w-fit">
              <Loader2 className="w-4 h-4 animate-spin" />
              <span>Retrieving AST chunks &amp; querying Gemini...</span>
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>

        {/* Suggested Queries */}
        <div className="px-4 py-2 bg-[#f7f3ec] border-t border-[#c8c5cb]/40 overflow-x-auto whitespace-nowrap">
          <div className="flex space-x-1.5">
            {sampleQueries.map((sq, i) => (
              <button
                key={i}
                onClick={() => handleSend(sq)}
                disabled={isQuerying}
                className="font-mono text-[10.5px] bg-[#ffffff] hover:bg-[#ece8e1] border border-[#c8c5cb] px-2.5 py-1 rounded text-[#47464b] hover:text-[#1c1c18] transition-all shrink-0"
              >
                {sq}
              </button>
            ))}
          </div>
        </div>

        {/* Input Bar */}
        <div className="p-3 border-t border-[#c8c5cb] bg-[#ffffff] flex items-center space-x-2">
          <textarea
            rows={1}
            value={inputQuery}
            onChange={(e) => setInputQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                handleSend();
              }
            }}
            placeholder="Ask anything about the codebase..."
            className="flex-1 bg-[#f7f3ec] border border-[#c8c5cb] rounded px-3 py-2 text-xs font-mono resize-none focus:border-[#835331] focus:outline-hidden"
          />

          <button
            onClick={() => handleSend()}
            disabled={!inputQuery.trim() || isQuerying}
            className="p-2.5 bg-[#1c1c18] text-[#ffffff] rounded hover:bg-[#2b2b30] disabled:opacity-40 transition-all cursor-pointer"
          >
            <CornerDownLeft className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

rawFiles.src/components/CodeExplorerView.tsx:
import React, { useState, useEffect } from 'react';
import {
  Folder,
  FolderOpen,
  FileCode,
  FileText,
  Search,
  Copy,
  Check,
  Sparkles,
  ChevronRight,
  ChevronDown,
  AlertTriangle,
  ShieldAlert,
  Loader2,
  Maximize2,
} from 'lucide-react';
import type { FileNode, Project } from '../types';
import { apiFetch } from '../services/api';

interface CodeExplorerViewProps {
  project: Project;
  initialFile?: string;
  initialLine?: number;
}

export const CodeExplorerView: React.FC<CodeExplorerViewProps> = ({
  project,
  initialFile,
  initialLine,
}) => {
  const [fileTree, setFileTree] = useState<FileNode[]>([]);
  const [selectedFile, setSelectedFile] = useState<string>(
    initialFile || (project.rawFiles ? Object.keys(project.rawFiles)[0] : '')
  );
  const [fileContent, setFileContent] = useState<string>('');
  const [isLoadingContent, setIsLoadingContent] = useState<boolean>(false);
  const [copied, setCopied] = useState<boolean>(false);
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [aiExplanation, setAiExplanation] = useState<string | null>(null);
  const [isExplaining, setIsExplaining] = useState<boolean>(false);
  const [expandedFolders, setExpandedFolders] = useState<Record<string, boolean>>({
    rpc: true,
    auth: true,
    runtime: true,
    engine: true,
    consensus: true,
    gateway: true,
    proto: true,
  });

  // Load tree
  useEffect(() => {
    apiFetch(`/api/projects/${project.id}/files`)
      .then((res) => res.json())
      .then((data) => {
        if (Array.isArray(data)) setFileTree(data);
      })
      .catch((err) => console.error('Failed to load file tree:', err));
  }, [project.id]);

  // Load file content when selectedFile changes
  useEffect(() => {
    if (!selectedFile) return;

    if (project.rawFiles && selectedFile in project.rawFiles) {
      setFileContent(project.rawFiles[selectedFile]);
      setAiExplanation(null);
      return;
    }

    setIsLoadingContent(true);
    apiFetch(`/api/projects/${project.id}/file-content?path=${encodeURIComponent(selectedFile)}`)
      .then((res) => res.json())
      .then((data) => {
        setFileContent(data.content || '');
        setAiExplanation(null);
      })
      .catch((err) => console.error('Failed to fetch file content:', err))
      .finally(() => setIsLoadingContent(false));
  }, [selectedFile, project.id, project.rawFiles]);

  // When initialFile changes from outside
  useEffect(() => {
    if (initialFile) {
      setSelectedFile(initialFile);
    }
  }, [initialFile]);

  const handleCopy = () => {
    navigator.clipboard.writeText(fileContent);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleExplain = async () => {
    if (!selectedFile || !fileContent) return;
    setIsExplaining(true);
    try {
      const res = await apiFetch(`/api/projects/${project.id}/explain-code`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          file: selectedFile,
          startLine: 1,
          endLine: Math.min(fileContent.split('\n').length, 80),
          code: fileContent.slice(0, 3000),
        }),
      });
      const data = await res.json();
      setAiExplanation(data.explanation || 'No explanation generated.');
    } catch (e) {
      setAiExplanation('Error communicating with Gemini intelligence engine.');
    } finally {
      setIsExplaining(false);
    }
  };

  const toggleFolder = (folderPath: string) => {
    setExpandedFolders((prev) => ({
      ...prev,
      [folderPath]: !prev[folderPath],
    }));
  };

  // Findings for the current file
  const fileFindings = [
    ...project.qualityFindings.filter((q) => q.file === selectedFile).map((q) => ({ type: 'quality', ...q })),
    ...project.securityFindings.filter((s) => s.file === selectedFile).map((s) => ({ type: 'security', ...s })),
  ];

  // Render tree node recursive
  const renderNode = (node: FileNode, depth = 0) => {
    if (node.type === 'directory') {
      const isExpanded = expandedFolders[node.path] !== false; // default expanded
      return (
        <div key={node.path} className="select-none">
          <div
            onClick={() => toggleFolder(node.path)}
            className="flex items-center space-x-1 px-2 py-1 rounded text-xs font-mono text-[#47464b] hover:bg-[#ece8e1] cursor-pointer"
            style={{ paddingLeft: `${depth * 14 + 8}px` }}
          >
            {isExpanded ? (
              <ChevronDown className="w-3 h-3 text-[#78767b]" />
            ) : (
              <ChevronRight className="w-3 h-3 text-[#78767b]" />
            )}
            {isExpanded ? (
              <FolderOpen className="w-3.5 h-3.5 text-[#835331]" />
            ) : (
              <Folder className="w-3.5 h-3.5 text-[#835331]" />
            )}
            <span className="truncate font-medium">{node.name}</span>
          </div>
          {isExpanded && node.children && (
            <div>{node.children.map((child) => renderNode(child, depth + 1))}</div>
          )}
        </div>
      );
    }

    // File
    const isSelected = selectedFile === node.path;
    const hasFinding = project.qualityFindings.some((q) => q.file === node.path) || project.securityFindings.some((s) => s.file === node.path);

    return (
      <div
        key={node.path}
        onClick={() => setSelectedFile(node.path)}
        className={`flex items-center justify-between px-2 py-1 rounded text-xs font-mono cursor-pointer transition-colors ${
          isSelected
            ? 'bg-[#1c1c18] text-[#ffffff] font-semibold'
            : 'text-[#1c1c18] hover:bg-[#f1ede6]'
        }`}
        style={{ paddingLeft: `${depth * 14 + 20}px` }}
      >
        <div className="flex items-center space-x-1.5 truncate">
          <FileCode className={`w-3.5 h-3.5 shrink-0 ${isSelected ? 'text-[#febf94]' : 'text-[#835331]'}`} />
          <span className="truncate">{node.name}</span>
        </div>
        {hasFinding && (
          <span
            className={`w-1.5 h-1.5 rounded-full shrink-0 ${
              isSelected ? 'bg-[#febf94]' : 'bg-[#ba1a1a]'
            }`}
          />
        )}
      </div>
    );
  };

  const lines = fileContent ? fileContent.split('\n') : [];

  return (
    <div className="space-y-4 max-w-6xl mx-auto pb-12">
      {/* Top Header */}
      <div className="flex items-center justify-between border-b border-[#c8c5cb]/50 pb-3">
        <div>
          <span className="font-mono text-[10px] text-[#835331] uppercase tracking-widest font-semibold">
            Repository Browser &bull; The Source
          </span>
          <h1 className="font-serif text-2xl sm:text-3xl font-medium text-[#1c1c18] tracking-tight">
            Code Explorer &amp; Static Inspector
          </h1>
        </div>

        <div className="flex items-center space-x-2">
          <button
            onClick={handleExplain}
            disabled={isExplaining}
            className="flex items-center space-x-1.5 bg-[#1c1c18] text-[#fdf9f2] px-3 py-1.5 rounded text-xs font-mono hover:bg-[#2b2b30] transition-all border-t border-[#c5a880]/40 disabled:opacity-50"
          >
            {isExplaining ? (
              <Loader2 className="w-3.5 h-3.5 animate-spin text-[#febf94]" />
            ) : (
              <Sparkles className="w-3.5 h-3.5 text-[#febf94]" />
            )}
            <span>Explain with Gemini</span>
          </button>
        </div>
      </div>

      {/* Explorer Workspace Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 items-start">
        {/* Left 3 Columns: File Tree */}
        <div className="lg:col-span-4 bg-[#ffffff] rounded-lg bevel-hairline p-3 space-y-2.5">
          <div className="flex items-center justify-between border-b border-[#c8c5cb]/40 pb-2">
            <span className="font-mono text-xs font-semibold text-[#1c1c18] uppercase tracking-wider">
              Files ({project.totalFiles})
            </span>
            <span className="font-mono text-[10px] text-[#78767b]">{project.name}</span>
          </div>

          {/* Search box */}
          <div className="relative">
            <Search className="w-3.5 h-3.5 text-[#78767b] absolute left-2.5 top-2.5" />
            <input
              type="text"
              placeholder="Filter file path..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-[#f7f3ec] border border-[#c8c5cb] pl-8 pr-2.5 py-1 text-xs font-mono rounded focus:border-[#835331] focus:outline-hidden"
            />
          </div>

          {/* File list */}
          <div className="max-h-[520px] overflow-y-auto space-y-0.5 pr-1">
            {searchQuery ? (
              Object.keys(project.rawFiles || {})
                .filter((p) => p.toLowerCase().includes(searchQuery.toLowerCase()))
                .map((p) => (
                  <div
                    key={p}
                    onClick={() => setSelectedFile(p)}
                    className={`px-2 py-1.5 text-xs font-mono rounded cursor-pointer truncate ${
                      selectedFile === p ? 'bg-[#1c1c18] text-[#ffffff]' : 'text-[#1c1c18] hover:bg-[#f1ede6]'
                    }`}
                  >
                    {p}
                  </div>
                ))
            ) : (
              fileTree.map((node) => renderNode(node))
            )}
          </div>
        </div>

        {/* Center / Right 8 Columns: Source Code Viewer & AI Context */}
        <div className="lg:col-span-8 space-y-3">
          {/* File breadcrumb & actions */}
          <div className="bg-[#f7f3ec] border border-[#c8c5cb] rounded px-3 py-2 flex items-center justify-between font-mono text-xs">
            <div className="flex items-center space-x-2 truncate">
              <span className="text-[#78767b]">{project.name} /</span>
              <span className="font-semibold text-[#1c1c18] truncate">{selectedFile}</span>
              <span className="text-[10px] bg-[#ece8e1] px-1.5 py-0.2 rounded border border-[#c8c5cb] text-[#47464b]">
                {lines.length} lines
              </span>
            </div>

            <button
              onClick={handleCopy}
              className="p-1 text-[#47464b] hover:text-[#1c1c18] rounded transition-colors flex items-center space-x-1"
              title="Copy source"
            >
              {copied ? <Check className="w-3.5 h-3.5 text-[#0e5138]" /> : <Copy className="w-3.5 h-3.5" />}
            </button>
          </div>

          {/* Code Viewer Panel */}
          <div className="bg-[#ffffff] rounded-lg bevel-hairline overflow-hidden">
            {isLoadingContent ? (
              <div className="p-12 text-center font-mono text-xs text-[#78767b] flex items-center justify-center space-x-2">
                <Loader2 className="w-4 h-4 animate-spin text-[#835331]" />
                <span>Loading source code...</span>
              </div>
            ) : (
              <div className="max-h-[520px] overflow-y-auto font-mono text-xs flex">
                {/* Line Numbers */}
                <div className="bg-[#f7f3ec] border-r border-[#c8c5cb]/40 py-3 px-2.5 text-right select-none text-[#78767b] shrink-0 min-w-[42px]">
                  {lines.map((_, i) => (
                    <div
                      key={i}
                      className={`leading-5 text-[11px] ${
                        initialLine === i + 1 ? 'text-[#835331] font-bold bg-[#febf94]/40 px-1 rounded-xs' : ''
                      }`}
                    >
                      {i + 1}
                    </div>
                  ))}
                </div>

                {/* Code Lines */}
                <div className="py-3 px-4 overflow-x-auto w-full">
                  {lines.map((lineText, i) => (
                    <div
                      key={i}
                      className={`leading-5 whitespace-pre font-mono text-[11.5px] ${
                        initialLine === i + 1 ? 'bg-[#ffdcc6]/50 rounded-xs' : ''
                      }`}
                    >
                      <span className="text-[#1c1c18]">{lineText || ' '}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* AI Explanation Drawer / Output */}
          {aiExplanation && (
            <div className="bg-[#ffffff] rounded-lg bevel-hairline p-4 space-y-2 border-l-4 border-l-[#835331]">
              <div className="flex items-center space-x-2 text-[#835331] font-mono text-xs font-semibold">
                <Sparkles className="w-4 h-4" />
                <span>Gemini Architectural Review for {selectedFile}</span>
              </div>
              <div className="font-sans text-xs text-[#1c1c18] leading-relaxed whitespace-pre-wrap bg-[#f7f3ec] p-3 rounded border border-[#c8c5cb]/50">
                {aiExplanation}
              </div>
            </div>
          )}

          {/* Findings in this file */}
          {fileFindings.length > 0 && (
            <div className="bg-[#f7f3ec] rounded-lg border border-[#c8c5cb] p-3 space-y-2">
              <div className="font-mono text-xs font-semibold text-[#1c1c18] flex items-center space-x-1.5">
                <AlertTriangle className="w-3.5 h-3.5 text-[#8a3b00]" />
                <span>Active Findings in this File ({fileFindings.length})</span>
              </div>
              <div className="space-y-1.5">
                {fileFindings.map((f, i) => (
                  <div
                    key={i}
                    className="p-2 bg-[#ffffff] rounded border border-[#c8c5cb]/50 text-xs font-mono flex items-start justify-between"
                  >
                    <div>
                      <span
                        className={`text-[9px] uppercase px-1 py-0.2 rounded font-bold mr-1.5 ${
                          f.type === 'security' ? 'bg-[#ffdad6] text-[#ba1a1a]' : 'bg-[#fef3eb] text-[#8a3b00]'
                        }`}
                      >
                        {f.severity}
                      </span>
                      <span className="font-medium text-[#1c1c18]">{f.title}</span>
                      <p className="text-[11px] text-[#47464b] font-sans mt-0.5">{f.description}</p>
                    </div>
                    <span className="text-[10px] text-[#78767b] shrink-0 ml-2">Line {f.line}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

rawFiles.src/components/ConnectWorkspaceView.tsx:
import React, { useState, useRef } from 'react';
import {
  UploadCloud,
  Github,
  FileArchive,
  Loader2,
  AlertCircle,
  CheckCircle2,
  ShieldAlert,
  ArrowRight,
  Terminal,
  Cpu,
  Layers,
  Sparkles,
} from 'lucide-react';
import type { Project, User } from '../types';
import { apiFetch } from '../services/api';

interface ConnectWorkspaceViewProps {
  user: User;
  onProjectImported: (project: Project) => void;
}

export const ConnectWorkspaceView: React.FC<ConnectWorkspaceViewProps> = ({
  user,
  onProjectImported,
}) => {
  const [activeMode, setActiveMode] = useState<'zip' | 'github'>('zip');

  // ZIP state
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [zipProjectName, setZipProjectName] = useState('');
  const [isDragOver, setIsDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // GitHub state
  const [githubUrl, setGithubUrl] = useState('');
  const [githubBranch, setGithubBranch] = useState('main');

  // Processing state
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStep, setProcessingStep] = useState<string>('INGEST');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const steps = [
    'INGEST',
    'SCAN',
    'AST INDEX',
    'DETECT VULNERABILITIES',
    'TOPOLOGY MAPPING',
    'CODEBASE SYNTHESIS',
  ];

  const cycleProcessingSteps = () => {
    let i = 0;
    const interval = setInterval(() => {
      i = (i + 1) % steps.length;
      setProcessingStep(steps[i]);
    }, 650);
    return interval;
  };

  // Upload ZIP
  const handleZipSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedFile) {
      setErrorMessage('Please select a .zip archive of your codebase.');
      return;
    }

    if (!selectedFile.name.toLowerCase().endsWith('.zip')) {
      setErrorMessage('File must be a .zip archive.');
      return;
    }

    setIsProcessing(true);
    setErrorMessage(null);
    const interval = cycleProcessingSteps();

    try {
      const reader = new FileReader();
      reader.onload = async () => {
        try {
          const base64 = (reader.result as string).split(',')[1];
          const res = await apiFetch('/api/projects/upload-zip', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              name: zipProjectName || selectedFile.name.replace(/\.zip$/i, ''),
              base64Zip: base64,
              filename: selectedFile.name,
            }),
          });

          clearInterval(interval);
          if (!res.ok) {
            const errData = await res.json().catch(() => ({ error: 'Upload failed' }));
            throw new Error(errData.error || 'Failed to analyze archive.');
          }

          const project = await res.json();
          onProjectImported(project);
        } catch (err: unknown) {
          clearInterval(interval);
          setIsProcessing(false);
          setErrorMessage(err instanceof Error ? err.message : 'Error processing ZIP file.');
        }
      };

      reader.onerror = () => {
        clearInterval(interval);
        setIsProcessing(false);
        setErrorMessage('Error reading file from disk.');
      };

      reader.readAsDataURL(selectedFile);
    } catch (err: unknown) {
      clearInterval(interval);
      setIsProcessing(false);
      setErrorMessage(err instanceof Error ? err.message : 'Upload failed.');
    }
  };

  // GitHub Import
  const handleGithubSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!githubUrl.trim()) {
      setErrorMessage('Please enter a GitHub repository URL or owner/repo format.');
      return;
    }

    setIsProcessing(true);
    setErrorMessage(null);
    const interval = cycleProcessingSteps();

    try {
      const res = await apiFetch('/api/projects/import-github', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          repoUrl: githubUrl.trim(),
          branch: githubBranch.trim() || 'main',
        }),
      });

      clearInterval(interval);
      if (!res.ok) {
        const errData = await res.json().catch(() => ({ error: 'Import failed' }));
        throw new Error(errData.error || 'Failed to import GitHub repository.');
      }

      const project = await res.json();
      onProjectImported(project);
    } catch (err: unknown) {
      clearInterval(interval);
      setIsProcessing(false);
      setErrorMessage(err instanceof Error ? err.message : 'Failed to import GitHub repository.');
    }
  };

  return (
    <div className="max-w-4xl mx-auto py-8 sm:py-12 px-4 space-y-8">
      {/* Welcome Banner */}
      <div className="text-center space-y-3">
        <div className="inline-flex items-center space-x-2 bg-[#ece8e1] px-3 py-1 rounded-full border border-[#c8c5cb] text-xs font-mono text-[#47464b]">
          <span className="w-2 h-2 rounded-full bg-[#835331] animate-pulse"></span>
          <span>Workspace Authenticated // {user.email}</span>
        </div>

        <h1 className="font-serif text-3xl sm:text-4xl font-bold tracking-tight text-[#1c1c18]">
          Connect Repository to Begin Analysis
        </h1>
        <p className="font-mono text-xs sm:text-sm text-[#78767b] max-w-xl mx-auto">
          No demo repositories loaded. Connect your codebase via public GitHub repository or upload a local .zip archive to initiate deterministic AST extraction, security scans, and architectural synthesis.
        </p>
      </div>

      {/* Main Connection Container */}
      <div className="bg-[#ffffff] border border-[#c8c5cb] rounded-lg shadow-sm overflow-hidden">
        {/* Method Selector Tabs */}
        <div className="grid grid-cols-2 border-b border-[#ece8e1] bg-[#f7f3ec]">
          <button
            type="button"
            onClick={() => {
              setActiveMode('zip');
              setErrorMessage(null);
            }}
            className={`py-3.5 px-4 flex items-center justify-center space-x-2 font-mono text-xs font-semibold tracking-wider transition-all border-b-2 ${
              activeMode === 'zip'
                ? 'border-[#835331] bg-[#ffffff] text-[#835331]'
                : 'border-transparent text-[#78767b] hover:text-[#1c1c18]'
            }`}
          >
            <UploadCloud className="w-4 h-4" />
            <span>Upload .ZIP Archive</span>
          </button>

          <button
            type="button"
            onClick={() => {
              setActiveMode('github');
              setErrorMessage(null);
            }}
            className={`py-3.5 px-4 flex items-center justify-center space-x-2 font-mono text-xs font-semibold tracking-wider transition-all border-b-2 ${
              activeMode === 'github'
                ? 'border-[#835331] bg-[#ffffff] text-[#835331]'
                : 'border-transparent text-[#78767b] hover:text-[#1c1c18]'
            }`}
          >
            <Github className="w-4 h-4" />
            <span>Connect GitHub Repo</span>
          </button>
        </div>

        {/* Error Alert */}
        {errorMessage && (
          <div className="m-6 p-3.5 bg-[#fff0f0] border border-[#ba1a1a]/30 rounded text-[#ba1a1a] flex items-start space-x-2.5 text-xs font-mono">
            <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
            <div>
              <p className="font-semibold">Analysis Ingestion Error</p>
              <p>{errorMessage}</p>
            </div>
          </div>
        )}

        {/* Processing State Overlay / Display */}
        {isProcessing ? (
          <div className="py-16 px-6 text-center space-y-6">
            <div className="relative inline-flex items-center justify-center">
              <div className="w-16 h-16 rounded-full border-2 border-[#835331]/20 border-t-[#835331] animate-spin"></div>
              <Cpu className="w-6 h-6 text-[#835331] absolute" />
            </div>

            <div className="space-y-2">
              <span className="font-mono text-xs font-bold uppercase tracking-widest text-[#835331] bg-[#fed3b8]/40 px-3 py-1 rounded border border-[#835331]/30">
                PIPELINE STEP: {processingStep}
              </span>
              <h3 className="font-serif text-xl font-bold text-[#1c1c18]">
                Analyzing Repository Architecture
              </h3>
              <p className="font-mono text-xs text-[#78767b] max-w-md mx-auto">
                Parsing source code tree, compiling AST metrics, computing system integrity, and mapping protocol tiers...
              </p>
            </div>

            {/* Pipeline Stage Indicators */}
            <div className="flex flex-wrap justify-center gap-2 max-w-lg mx-auto pt-2">
              {steps.map((s) => (
                <span
                  key={s}
                  className={`font-mono text-[10px] px-2 py-0.5 rounded border transition-colors ${
                    s === processingStep
                      ? 'bg-[#1c1c18] text-[#ffffff] border-[#1c1c18]'
                      : 'bg-[#f7f3ec] text-[#78767b] border-[#c8c5cb]'
                  }`}
                >
                  {s}
                </span>
              ))}
            </div>
          </div>
        ) : (
          <div className="p-6 sm:p-8">
            {/* MODE 1: ZIP Archive Upload */}
            {activeMode === 'zip' && (
              <form onSubmit={handleZipSubmit} className="space-y-6">
                {/* Drag and drop area */}
                <div
                  onDragOver={(e) => {
                    e.preventDefault();
                    setIsDragOver(true);
                  }}
                  onDragLeave={() => setIsDragOver(false)}
                  onDrop={(e) => {
                    e.preventDefault();
                    setIsDragOver(false);
                    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
                      setSelectedFile(e.dataTransfer.files[0]);
                      setErrorMessage(null);
                    }
                  }}
                  onClick={() => fileInputRef.current?.click()}
                  className={`border-2 border-dashed rounded-lg p-8 sm:p-12 text-center cursor-pointer transition-all ${
                    isDragOver
                      ? 'border-[#835331] bg-[#fed3b8]/20'
                      : selectedFile
                      ? 'border-[#835331] bg-[#fdf9f2]'
                      : 'border-[#c8c5cb] hover:border-[#835331] bg-[#fbf8f2]'
                  }`}
                >
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept=".zip"
                    className="hidden"
                    onChange={(e) => {
                      if (e.target.files && e.target.files[0]) {
                        setSelectedFile(e.target.files[0]);
                        setErrorMessage(null);
                      }
                    }}
                  />

                  {selectedFile ? (
                    <div className="flex flex-col items-center space-y-2">
                      <div className="w-12 h-12 rounded-full bg-[#835331]/10 text-[#835331] flex items-center justify-center">
                        <FileArchive className="w-6 h-6" />
                      </div>
                      <span className="font-mono text-sm font-bold text-[#1c1c18]">
                        {selectedFile.name}
                      </span>
                      <span className="font-mono text-xs text-[#78767b]">
                        {(selectedFile.size / (1024 * 1024)).toFixed(2)} MB archive selected
                      </span>
                      <span className="text-xs font-mono text-[#835331] underline pt-1">
                        Click or drag to choose another file
                      </span>
                    </div>
                  ) : (
                    <div className="flex flex-col items-center space-y-3">
                      <div className="w-12 h-12 rounded-full bg-[#ece8e1] text-[#835331] flex items-center justify-center border border-[#c8c5cb]">
                        <UploadCloud className="w-6 h-6" />
                      </div>
                      <div className="space-y-1">
                        <p className="font-serif text-lg font-bold text-[#1c1c18]">
                          Drop your source code .zip archive here
                        </p>
                        <p className="font-mono text-xs text-[#78767b]">
                          Supports Go, TypeScript, Rust, Python, Java, C++, and Protobuf projects
                        </p>
                      </div>
                      <span className="inline-flex items-center space-x-1.5 px-3 py-1 bg-[#ffffff] border border-[#c8c5cb] rounded text-xs font-mono text-[#1c1c18] shadow-2xs hover:bg-[#ece8e1]">
